BEGIN;

DELETE FROM questions WHERE topic = 'Reproduction' AND subtopic IN ('Female Hormones: Estrogen & Progesterone', 'Male Hormonal Axis', 'Pregnancy & Menopause', 'Sexual Development & Puberty', 'The Menstrual Cycle');

-- Q1 [Sexual Development & Puberty | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub1$Sexual Development & Puberty$sub1$, $qt1$A geneticist examines a 46,XY embryo and finds that its bipotential gonads have begun differentiating into testes, with germ cells becoming spermatogonia. The presence of which Y-chromosome gene best accounts for this redirection toward testis formation?$qt1$, $op1$[{"label": "A", "text": "The SRY gene, which recruits testis-development genes and suppresses female-development genes in the bipotential gonad"}, {"label": "B", "text": "The GnRH gene, whose hypothalamic product drives gonadal differentiation toward a testis in the fetus"}, {"label": "C", "text": "The gene encoding the testosterone receptor, whose presence on the Y chromosome converts the gonad into a testis"}, {"label": "D", "text": "An FSH-encoding gene on the Y chromosome that stimulates the fetal bipotential gonad to become a testis"}]$op1$::jsonb, 'A', $ex1$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is A because the SRY (Sex-determining Region of the Y chromosome) gene is the single Y-chromosome gene that redirects the bipotential gonad toward a testis. The text states that "to become a male, an individual must be exposed to the cascade of factors initiated by a single gene on the male Y chromosome... the SRY," and that "the SRY gene actively recruits other genes that begin to develop the testes, and suppresses genes that are important in female development," with germ cells differentiating into spermatogonia as part of this SRY-prompted cascade. Without a functional SRY gene, oogonia form and the individual develops as female, confirming SRY as the determining switch. (Choice A) is correct because SRY is the Y-chromosome gene that recruits testis genes and suppresses female-development genes in the bipotential gonad. (Choice B) is wrong because GnRH is a hypothalamic hormone that initiates puberty by stimulating the anterior pituitary, not a fetal sex-determining gene. (Choice C) is wrong because testosterone acts downstream after the testis already forms (Leydig cells secrete testosterone "soon after the formation of the testis"), so a testosterone receptor cannot be the gene that creates the testis. (Choice D) is wrong because FSH is a pituitary gonadotropin that promotes gamete production and follicular growth at puberty, not a Y-chromosome gene that determines fetal gonad identity. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the established fact that SRY is the specific Y-chromosome gene responsible for directing the bipotential gonad to develop into a testis.$ex1$, 'easy', '3B', $cc1$Reproductive Endocrinology (BIO)$cc1$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a1B$Confuses the puberty-axis trigger (GnRH) with the fetal sex-determining gene$a1B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a1C$Testosterone acts downstream after the testis already forms, not as the determining gene$a1C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a1D$FSH is a pituitary gonadotropin acting at puberty, mistaken for a fetal gonad determinant$a1D$ FROM q;

-- Q2 [Sexual Development & Puberty | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub2$Sexual Development & Puberty$sub2$, $qt2$A 12-year-old enters puberty, and clinicians trace the first detectable rise in the gonadotropins FSH and LH back to a single hormone arriving at the anterior pituitary from the hypothalamus. Which hormone provides this hypothalamic signal?$qt2$, $op2$[{"label": "A", "text": "Luteinizing hormone (LH), sent from the hypothalamus to the anterior pituitary to trigger gonadotropin release"}, {"label": "B", "text": "Gonadotropin-releasing hormone (GnRH), sent from the hypothalamus to the anterior pituitary to cause release of FSH and LH"}, {"label": "C", "text": "Testosterone, secreted by the gonads to stimulate the anterior pituitary to release FSH and LH"}, {"label": "D", "text": "Inhibin, released by the gonads to signal the anterior pituitary to secrete FSH and LH"}]$op2$::jsonb, 'B', $ex2$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is B because gonadotropin-releasing hormone (GnRH) is the hypothalamic hormone that, at the onset of puberty, travels to the anterior pituitary and stimulates it to secrete the gonadotropins FSH and LH. OpenStax Anatomy & Physiology 2e states that "Puberty is initiated by gonadotropin-releasing hormone (GnRH), a hormone produced and secreted by the hypothalamus. GnRH stimulates the anterior pituitary to secrete gonadotropins," and OpenStax Biology 2e confirms that "the hypothalamus produces gonadotropin-releasing hormone (GnRH), which stimulates the production and release of follicle-stimulating hormone (FSH) and luteinizing hormone (LH) from the anterior pituitary gland." FSH and LH are themselves the pituitary outputs of this signal, while testosterone and inhibin are gonadal hormones that lie downstream and feed back to suppress the axis, not initiate it. (Choice A) LH is wrong because LH is one of the gonadotropins released by the anterior pituitary in response to GnRH, not the hypothalamic input that triggers their release. (Choice B) GnRH is correct because it is the hypothalamic hormone that signals the anterior pituitary to release FSH and LH. (Choice C) Testosterone is wrong because it is a gonadal sex hormone that lies downstream of the axis and, at high concentrations, inhibits GnRH and gonadotropin release rather than stimulating it. (Choice D) Inhibin is wrong because it is a gonadal hormone that suppresses FSH release from the pituitary, the opposite of triggering its secretion. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the identity and directional role of GnRH within the hypothalamic-pituitary-gonadal axis at puberty.$ex2$, 'easy', '3B', $cc2$Reproductive Endocrinology (BIO)$cc2$, 'biology', 1, 70
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a2A$Naming a pituitary gonadotropin output (LH) as the hypothalamic input$a2A$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a2C$Substituting a downstream gonadal sex hormone for the hypothalamic trigger$a2C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a2D$Treating an FSH-suppressing gonadal hormone (inhibin) as an FSH/LH trigger$a2D$ FROM q;

-- Q3 [Sexual Development & Puberty | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub3$Sexual Development & Puberty$sub3$, $qt3$A pediatric endocrinologist administers a very small dose of estrogen to a healthy 6-year-old and measures circulating GnRH, LH, and FSH afterward. All three hormones fall to strikingly low levels—a far steeper suppression than the same dose would produce in an adult. Which mechanism best accounts for this exaggerated drop?$qt3$, $op3$[{"label": "A", "text": "The prepubertal gonads are extremely sensitive to FSH and LH, amplifying the small steroid dose into strong suppression of the axis."}, {"label": "B", "text": "The child has not yet begun pulsatile GnRH secretion, so the exogenous steroid halts a pulse generator that was already completely silent."}, {"label": "C", "text": "The prepubertal hypothalamus and pituitary are highly sensitive to negative feedback, so even low steroid concentrations strongly suppress GnRH, LH, and FSH."}, {"label": "D", "text": "The prepubertal anterior pituitary cannot yet synthesize FSH and LH, so the administered steroid has no gonadotropins on which to act."}]$op3$::jsonb, 'C', $ex3$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is C because in prepubertal children the negative-feedback sensitivity of the hypothalamus and pituitary is very high, so even very low concentrations of sex steroids feed back strongly to keep GnRH, LH, and FSH production low. OpenStax Anatomy & Physiology 2e states, "In pre-pubertal children, the sensitivity of the negative feedback system in the hypothalamus and pituitary is very high. This means that very low concentrations of androgens or estrogens will negatively feed back onto the hypothalamus and pituitary, keeping the production of GnRH, LH, and FSH low." The transition into puberty requires a decrease in this feedback sensitivity, "meaning that it takes increasingly larger concentrations of sex steroid hormones to stop the production of LH and FSH." A child's axis therefore responds to a tiny steroid dose with the steep suppression observed here, whereas an adult's desensitized axis would not. (Choice A) Increased gonadal sensitivity to FSH and LH is a separate pubertal change that makes the gonads more responsive to gonadotropins; it acts downstream and would not drive feedback suppression of the central axis. (Choice B) GnRH secretion is restrained, not absent, before puberty—nocturnal pulsatile LH release is already detectable years before physical changes—so the pulse generator is not "completely silent," and feedback sensitivity is the operative reason. (Choice C) High central negative-feedback sensitivity to low sex-steroid levels is exactly the documented prepubertal mechanism, so this is correct. (Choice D) The prepubertal anterior pituitary does produce gonadotropins—detectable LH appears around age eight or nine, before puberty—so the claim that no gonadotropins exist is false. This is a Scientific Reasoning and Problem Solving question because it requires inferring from an experimental result (exaggerated gonadotropin suppression after a low steroid dose) which underlying property of the immature reproductive axis—feedback sensitivity—explains the data.$ex3$, 'medium', '3B', $cc3$Reproductive Endocrinology (BIO)$cc3$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a3A$Attributing the suppression to increased gonadal sensitivity, which is the real pubertal change but acts downstream and cannot produce central feedback suppression$a3A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a3B$Claiming GnRH secretion is wholly absent before puberty when it is restrained but detectable, missing that feedback sensitivity is the operative reason$a3B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a3D$Believing the prepubertal pituitary cannot make gonadotropins when low-level LH is already detectable before puberty$a3D$ FROM q;

-- Q4 [Sexual Development & Puberty | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub4$Sexual Development & Puberty$sub4$, $qt4$A geneticist studies an XY fetus in which the Leydig cells of the developing gonad carry a mutation that abolishes androgen synthesis, although every other testicular cell type functions normally. Based on the hormonal control of sexual development, the geneticist predicts the fetus will form which combination of structures?$qt4$, $op4$[{"label": "A", "text": "No gonads of either type, because Leydig-cell testosterone is required to direct the bipotential gonad to become a testis"}, {"label": "B", "text": "Testes plus fully masculinized external genitalia, because Sertoli-cell secretions alone drive both gonadal and external genital development"}, {"label": "C", "text": "Ovaries instead of testes, because the gonad reverts to the default female pathway when testosterone is absent despite the Y chromosome"}, {"label": "D", "text": "Testes that form normally, but external genitalia and the Wolffian duct that fail to masculinize because testosterone is absent"}]$op4$::jsonb, 'D', $ex4$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is D because the SRY gene, not testosterone, directs the bipotential gonad to become a testis, so testes still form even when Leydig cells cannot make androgen; however, the masculinization of the bipotential external genitalia and the maintenance of the Wolffian duct both depend on Leydig-cell testosterone, so these fail to masculinize when testosterone is absent. The text states that the SRY cascade "actively recruits other genes that begin to develop the testes" and that only "soon after the formation of the testis, the Leydig cells begin to secrete testosterone," confirming that testis formation precedes and does not require testosterone (A&P 2e, lines 56891-56896). Because "with exposure to testosterone, cells that could become either the glans penis or the glans clitoris form the glans penis" while "without testosterone, these same cells differentiate into the clitoris," the bipotential external genitalia cannot masculinize without androgen (A&P 2e, lines 56897-56899); likewise "without testosterone, the Wolffian duct will degrade" (A&P 2e, lines 56906-56907). (Choice A) is wrong because the testis forms under the SRY cascade before any testosterone is secreted, so androgen loss does not abolish gonad formation. (Choice B) is wrong because Sertoli (sustentacular) cell secretions only trigger regression of the Müllerian duct and do not masculinize the external genitalia, which require testosterone. (Choice C) is wrong because gonadal sex is set by SRY upstream of testosterone, so a Y-bearing gonad still becomes a testis rather than reverting to an ovary. (Choice D) is correct because the testis-determining SRY pathway is independent of androgen, whereas masculinization of the external genitalia and Wolffian duct specifically depends on Leydig-cell testosterone. This is a Scientific Reasoning and Problem Solving question because it requires applying the separation between SRY-driven gonadal determination and testosterone-driven genital differentiation to predict the outcome of a specific androgen-deficiency scenario.$ex4$, 'medium', '3B', $cc4$Reproductive Endocrinology (BIO)$cc4$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a4A$Inverts the causal direction so that testosterone, rather than SRY, is treated as the determinant of testis formation$a4A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a4B$Correctly recalls a real Sertoli-cell role (Müllerian regression) but overextends it to claim Sertoli secretions also masculinize the external genitalia$a4B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a4C$Collapses two sequential steps, applying the testosterone-absence default-female rule to the upstream gonadal-determination step that is governed by SRY$a4C$ FROM q;

-- Q5 [Sexual Development & Puberty | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub5$Sexual Development & Puberty$sub5$, $qt5$A pediatric endocrinologist tracks a healthy child across the transition into puberty and monitors both the responsiveness of the hypothalamic-pituitary axis to circulating sex steroids and the responsiveness of the gonads to gonadotropins. As puberty begins, she predicts the direction of these two sensitivity changes and the resulting shifts in LH/FSH and sex-steroid concentrations.$qt5$, $op5$[{"label": "A", "text": "Hypothalamic-pituitary sensitivity to negative feedback falls while gonadal sensitivity to gonadotropins rises, so LH and FSH climb and sex-hormone output increases."}, {"label": "B", "text": "Hypothalamic-pituitary sensitivity to negative feedback rises while gonadal sensitivity to gonadotropins rises, so LH and FSH fall while sex-hormone output increases."}, {"label": "C", "text": "Hypothalamic-pituitary sensitivity to negative feedback falls while gonadal sensitivity to gonadotropins drops, so the gonads enlarge only because sex-hormone output overrides weak LH and FSH."}, {"label": "D", "text": "Hypothalamic-pituitary gonadotropin output falls while adrenal androgens compensate, so sex-hormone levels rise even though LH and FSH decline throughout puberty."}]$op5$::jsonb, 'A', $ex5$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is A because puberty is initiated by two simultaneous sensitivity changes: a decrease in hypothalamic-pituitary sensitivity to negative feedback and an increase in gonadal sensitivity to gonadotropins. The text states that "as an individual approaches puberty, two changes in sensitivity occur. The first is a decrease of sensitivity in the hypothalamus and pituitary to negative feedback... The second change in sensitivity is an increase in sensitivity of the gonads to the FSH and LH signals." Because the brain no longer shuts down at low sex-steroid levels, "the levels of LH and FSH slowly increase and lead to the enlargement and maturation of the gonads, which in turn leads to secretion of higher levels of sex hormones." Thus LH/FSH and circulating sex steroids both climb together. (Choice A) is correct: falling feedback sensitivity plus rising gonadal sensitivity together raise LH/FSH and sex-hormone output. (Choice B) reverses the feedback change; increased sensitivity to negative feedback is the high-sensitivity prepubertal state in which "very low concentrations of androgens or estrogens will negatively feed back... keeping the production of GnRH, LH, and FSH low," so it would lower, not raise, gonadotropins. (Choice C) keeps the correct feedback change but inverts the gonadal change, and falling gonadal responsiveness with weak LH/FSH cannot explain the higher sex-hormone output the text attributes to gonadal maturation. (Choice D) is a distractor built on adrenal androgens; although the body must reach puberty for the adrenals to act, the text shows pubertal LH and FSH rise rather than fall and drive gonadal maturation. This is a Scientific Reasoning and Problem Solving question because it requires chaining the two sensitivity changes through the hypothalamic-pituitary-gonadal feedback loop to predict the coordinated direction of gonadotropin and sex-steroid levels.$ex5$, 'hard', '3B', $cc5$Reproductive Endocrinology (BIO)$cc5$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a5B$Inverting the feedback-sensitivity change so increased sensitivity is wrongly paired with puberty instead of the prepubertal state$a5B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a5C$One correct sensitivity change paired with an inverted gonadal change that contradicts rising sex-hormone output$a5C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a5D$Real adrenal-androgen contribution used to wrongly claim falling LH/FSH during puberty$a5D$ FROM q;

-- Q6 [Male Hormonal Axis | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub6$Male Hormonal Axis$sub6$, $qt6$A researcher infuses a man with a monoclonal antibody that blocks the receptors on his interstitial (Leydig) cells, then measures the resulting drop in testosterone synthesis to identify which anterior-pituitary hormone normally binds those receptors to drive testosterone production. Which hormone has its action interrupted by the antibody?$qt6$, $op6$[{"label": "A", "text": "Follicle-stimulating hormone (FSH), the gonadotropin that binds Sertoli cells of the seminiferous tubules to support sperm maturation"}, {"label": "B", "text": "Luteinizing hormone (LH), the gonadotropin that binds the interstitial (Leydig) cells and upregulates their production of testosterone"}, {"label": "C", "text": "Gonadotropin-releasing hormone (GnRH), the hypothalamic hormone that triggers the anterior pituitary to secrete its gonadotropins"}, {"label": "D", "text": "Inhibin, the testicular hormone secreted by Sertoli cells that feeds back to suppress FSH release from the pituitary"}]$op6$::jsonb, 'B', $ex6$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is B because luteinizing hormone is the anterior-pituitary gonadotropin that binds receptors on the interstitial (Leydig) cells and upregulates their synthesis of testosterone. The text states that "LH binds to receptors on Leydig cells in the testes and upregulates the production of testosterone," and because of this role LH "is also called interstitial cell-stimulating hormone." Blocking the Leydig-cell receptors therefore interrupts LH's action specifically, cutting off the signal that drives testosterone production. (Choice A) is incorrect because FSH "binds predominantly to the Sertoli cells within the seminiferous tubules to promote spermatogenesis," not the Leydig cells. (Choice B) is correct because LH is the gonadotropin whose receptors sit on the Leydig cells and whose binding upregulates testosterone synthesis. (Choice C) is incorrect because GnRH acts upstream on the anterior pituitary—"Binding of GnRH to its receptors on the anterior pituitary gland stimulates release of the two gonadotropins"—rather than directly on Leydig cells. (Choice D) is incorrect because inhibin is a testicular feedback hormone that the Sertoli cells produce to "inhibit FSH release from the pituitary," not a pituitary hormone that stimulates Leydig cells. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the established identity and target cell of the gonadotropin (LH) that directly stimulates Leydig-cell testosterone synthesis.$ex6$, 'easy', '3B', $cc6$Reproductive Endocrinology (BIO)$cc6$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a6A$Names the other gonadotropin (FSH), which is real and pituitary-derived but targets Sertoli cells, not Leydig cells$a6A$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a6C$Names the upstream hypothalamic hormone (GnRH) that acts on the pituitary one step earlier in the axis, not directly on Leydig cells$a6C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a6D$Names a testicular feedback hormone (inhibin) and miscasts it as a pituitary hormone that stimulates Leydig cells$a6D$ FROM q;

-- Q7 [Male Hormonal Axis | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub7$Male Hormonal Axis$sub7$, $qt7$A researcher administers an antibody that blocks FSH receptors on the Sertoli cells of an adult male's testes but leaves all other hormone receptors, including the LH receptors on the Leydig cells, fully functional. She then measures sperm maturation and circulating testosterone.$qt7$, $op7$[{"label": "A", "text": "Both sperm maturation and testosterone secretion fail, because FSH is also required to drive Leydig-cell testosterone production."}, {"label": "B", "text": "Testosterone secretion drops while sperm maturation is preserved, because FSH normally acts directly on the Leydig cells."}, {"label": "C", "text": "Sperm maturation is impaired while testosterone secretion continues, because LH still drives the Leydig cells once FSH signaling is lost."}, {"label": "D", "text": "Sperm maturation is impaired while circulating inhibin rises, because FSH-deprived Sertoli cells secrete more inhibin than before."}]$op7$::jsonb, 'C', $ex7$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is C because blocking FSH receptors removes the Sertoli-cell signal that drives spermatogenesis, while LH continues to stimulate the Leydig cells, so testosterone output is unaffected. The text states that in the testes "FSH binds predominantly to the Sertoli cells within the seminiferous tubules to promote spermatogenesis" and, separately, that "LH binds to receptors on Leydig cells in the testes and upregulates the production of testosterone." Because the two gonadotropins act on different cell populations through different receptors, an antibody that blocks only FSH receptors silences the Sertoli (spermatogenic) arm while leaving the LH–Leydig (testosterone) arm intact. (Choice A) is wrong because Leydig-cell testosterone is driven by LH, not FSH, so testosterone production does not require FSH. (Choice B) reverses the cellular targets: FSH acts on Sertoli cells, not Leydig cells, so blocking FSH does not lower LH-driven testosterone. (Choice C) is correct because the Sertoli (FSH) arm fails while the Leydig (LH) arm keeps secreting testosterone. (Choice D) is wrong because FSH stimulates Sertoli cells to produce inhibins, so removing FSH signaling lowers inhibin rather than raising it. This is a Scientific Reasoning and Problem Solving question because it requires predicting the selective experimental outcome of a targeted receptor blockade by separating which gonadotropin acts on which testicular cell type.$ex7$, 'medium', '3B', $cc7$Reproductive Endocrinology (BIO)$cc7$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a7A$Believing FSH (rather than LH) drives Leydig-cell testosterone, so both arms collapse$a7A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a7B$Swapping the cellular targets so FSH is thought to act on Leydig cells$a7B$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a7D$Correctly identifying the Sertoli arm but reversing the direction of FSH's effect on inhibin$a7D$ FROM q;

-- Q8 [Male Hormonal Axis | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub8$Male Hormonal Axis$sub8$, $qt8$A boy reaches the age of puberty, but a defect in his testicular interstitial (Leydig) cells leaves circulating testosterone at near-zero levels, even though his anterior pituitary releases FSH and LH normally. Assuming all other endocrine signaling is intact, which outcome should a physiologist most directly predict for this boy as adolescence proceeds?$qt8$, $op8$[{"label": "A", "text": "His seminiferous tubules and ductus deferens fail to form, because testosterone is required to build this duct anatomy at puberty."}, {"label": "B", "text": "FSH secretion from his anterior pituitary collapses, removing the pituitary signal that produces the male secondary sex characteristics."}, {"label": "C", "text": "His voice deepens and facial hair appears on schedule, but his libido and sperm production are the only functions that fail to develop."}, {"label": "D", "text": "The secondary sex characteristics testosterone normally drives—voice deepening, facial and body hair, and muscle and skeletal growth—fail to develop."}]$op8$::jsonb, 'D', $ex8$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is D because testosterone from the Leydig cells is the hormone responsible for the male secondary sex characteristics that emerge at puberty, so when testosterone is essentially absent, those characteristics fail to develop. OpenStax Biology 2e states that "Testosterone, the hormone responsible for the secondary sexual characteristics that develop in the male during adolescence... These secondary sex characteristics include a deepening of the voice, the growth of facial, axillary, and pubic hair," and OpenStax Biology 2e further notes testosterone drives "a suite of secondary sex characteristics, such as... increased skeletal and muscular growth, enlargement of the larynx, increased growth and redistribution of body hair." Because the pituitary still releases LH and FSH normally, the failure point is downstream at the Leydig cells, and the LH→Leydig→testosterone→secondary-characteristics pathway is broken, so voice deepening, facial and body hair, and muscle and skeletal growth do not appear. (Choice A) is wrong because the seminiferous tubules and the ductus deferens (a Wolffian-duct derivative) are laid down during embryonic development, not built at puberty, as OpenStax A&P 2e explains that these internal structures "form from one of two rudimentary duct systems in the embryo." (Choice B) is wrong because FSH does not collapse and does not drive secondary sex characteristics; FSH "stimulates the Sertoli cells to begin facilitating spermatogenesis," and the pituitary is functioning normally in this scenario. (Choice C) is a partial truth because testosterone does support libido and spermatogenesis, but it also drives the secondary sex characteristics, so the voice and facial hair would likewise fail to develop rather than appearing on schedule. (Choice D) is correct because testosterone is the direct driver of these secondary sex characteristics, and its near-absence prevents their development. This is a Scientific Reasoning and Problem Solving question because it requires predicting a downstream phenotypic outcome from a specified lesion in the male hormonal axis rather than recalling a stated fact.$ex8$, 'medium', '3B', $cc8$Reproductive Endocrinology (BIO)$cc8$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a8A$Attributing embryonic duct anatomy formation to the pubertal hormonal role being tested$a8A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a8B$Crediting FSH rather than testosterone with driving male secondary sex characteristics$a8B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a8C$Correctly losing libido/spermatogenesis but wrongly sparing the visible secondary sex characteristics$a8C$ FROM q;

-- Q9 [Male Hormonal Axis | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub9$Male Hormonal Axis$sub9$, $qt9$A bodybuilder injects high doses of a synthetic androgen for several months, driving his blood testosterone far above the normal range. A clinician who later examines him predicts that his testes will have shrunk and his sperm count will have dropped. Which sequence of hormonal events best accounts for this prediction?$qt9$, $op9$[{"label": "A", "text": "The high blood androgen binds androgen receptors on the hypothalamus and anterior pituitary, suppressing GnRH and LH, so Leydig cells lose stimulation and intratesticular testosterone falls, impairing spermatogenesis."}, {"label": "B", "text": "The high blood androgen drives the hypothalamus to release more GnRH and the pituitary to release more LH, so Leydig cells are stimulated harder and the testes enlarge as spermatogenesis speeds up."}, {"label": "C", "text": "The high blood androgen is delivered directly to the seminiferous tubules, raising intratesticular testosterone above normal, so spermatogenesis accelerates even though the testes appear smaller."}, {"label": "D", "text": "The high blood androgen suppresses GnRH and LH, but FSH continues to drive the Sertoli cells independently of intratesticular testosterone, so spermatogenesis is preserved despite the feedback."}]$op9$::jsonb, 'A', $ex9$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is A because chronically elevated blood androgen feeds back negatively on the brain: testosterone binds androgen receptors on both the hypothalamus and the anterior pituitary, inhibiting the synthesis and secretion of GnRH and LH. With LH withdrawn, the Leydig cells lose their stimulus and make far less local testosterone, and because intratesticular testosterone normally runs about 100 times higher than circulating testosterone and is required to promote spermatogenesis, its collapse causes sperm production to fall and the testes to atrophy. The high blood concentration of the synthetic androgen cannot substitute, because the seminiferous tubules depend on the high local concentration that only LH-stimulated Leydig cells can supply. (Choice A) is correct: suppressed GnRH and LH cut Leydig stimulation, intratesticular testosterone drops, and spermatogenesis fails. (Choice B) reverses the feedback sign, since high testosterone inhibits rather than stimulates GnRH and LH release, so the testes cannot be driven to enlarge. (Choice C) is a misconception, because external testosterone shuts down LH, so local intratesticular testosterone actually falls rather than rising, impairing spermatogenesis. (Choice D) is a partial truth, since the GnRH and LH suppression is real, but rising testosterone also feeds back to lower FSH, and the loss of intratesticular testosterone still impairs spermatogenesis, so sperm production is not preserved. This is a Scientific Reasoning and Problem Solving question because it requires tracing a multi-step negative-feedback chain from an exogenous perturbation to a downstream tissue-level outcome rather than recalling a single fact.$ex9$, 'hard', '3B', $cc9$Reproductive Endocrinology (BIO)$cc9$, 'biology', 2, 160
  ) RETURNING id
)
