UNION ALL SELECT id, 'B', 'reversed_relationship', $a10B$Swaps the arm inhibin targets, assigning inhibin feedback to the LH/Leydig arm instead of FSH$a10B$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a10D$Correct selective FSH fall but wrongly infers Sertoli/FSH arm gates Leydig testosterone, predicting a testosterone rise$a10D$ FROM q;

-- Q11 [Female Hormones: Estrogen & Progesterone | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub11$Female Hormones: Estrogen & Progesterone$sub11$, $qt11$A clinician studies a developing follicle that, under FSH stimulation, releases increasing amounts of estrogen during the first half of the ovarian cycle. Which physiological change is produced directly by this estrogen as it acts on its target tissues?$qt11$, $op11$[{"label": "A", "text": "Rupture of the dominant follicle and expulsion of the oocyte into the peritoneal cavity"}, {"label": "B", "text": "Development of egg cells within the follicles of the ovary"}, {"label": "C", "text": "Regrowth and thickening of the endometrial lining and breast development"}, {"label": "D", "text": "Maintenance of an already-thickened endometrium during the post-ovulatory luteal phase"}]$op11$::jsonb, 'C', $ex11$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is C because estrogen released from the developing follicle directly assists in endometrial regrowth and is responsible for female secondary sexual characteristics such as breast development. OpenStax Biology 2e states that "Estrogen is the reproductive hormone in females that assists in endometrial regrowth... it is also responsible for the secondary sexual characteristics of females. These include breast development." This pairing of endometrial thickening plus secondary sex characteristics is the defining direct action of estrogen, distinguishing it from the gonadotropins (FSH/LH) and from progesterone. (Choice A) Rupture of the dominant follicle and oocyte expulsion is triggered by the LH surge, not by estrogen itself; per OpenStax A&P 2e, "this large burst of LH (called the LH surge) that leads to ovulation of the dominant follicle." (Choice B) Development of egg cells within follicles is stimulated by FSH, not estrogen, since "FSH stimulates development of egg cells, called ova, which develop in structures called follicles." (Choice C) is correct because estrogen drives both endometrial regrowth and female secondary sex characteristics including breast development. (Choice D) Maintenance of the already-thickened endometrium after ovulation belongs to progesterone from the corpus luteum during the luteal phase, where "The progesterone facilitates the regrowth of the uterine lining." This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the specific, direct physiological action attributed to estrogen and separating it from the established roles of FSH, LH, and progesterone.$ex11$, 'easy', '3B', $cc11$Reproductive Endocrinology (BIO)$cc11$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a11A$Attributing the LH-surge-triggered ovulation event to estrogen, reversing the actual cause-effect direction$a11A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a11B$Assigning FSH's role of stimulating ova/follicle development to estrogen$a11B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a11D$Confusing estrogen's follicular-phase action with progesterone's luteal-phase maintenance of the endometrium$a11D$ FROM q;

-- Q12 [Female Hormones: Estrogen & Progesterone | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub12$Female Hormones: Estrogen & Progesterone$sub12$, $qt12$A clinician tracks a patient's hormone levels in the days immediately following ovulation and observes a steep, sustained rise in circulating progesterone that thickens the endometrium in preparation for a possible zygote. Which structure is releasing this progesterone, and what triggered its formation?$qt12$, $op12$[{"label": "A", "text": "The anterior pituitary, which begins secreting progesterone directly once the LH surge subsides."}, {"label": "B", "text": "The dominant follicle, whose granulosa and theca cells make progesterone their main product during the follicular phase."}, {"label": "C", "text": "The corpus albicans, which secretes progesterone as it degrades to sustain the endometrium late in the cycle."}, {"label": "D", "text": "The corpus luteum, which the LH-driven luteinization of the collapsed follicle converts into a progesterone-secreting structure."}]$op12$::jsonb, 'D', $ex12$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is D because after ovulation the LH surge triggers luteinization, transforming the collapsed follicle into the corpus luteum, whose luteinized granulosa and theca cells secrete large amounts of progesterone to maintain the endometrium for a potential pregnancy. The text states that luteinization 'transforms the collapsed follicle into a new endocrine structure called the corpus luteum,' and that 'the luteinized granulosa and theca cells of the corpus luteum begin to produce large amounts of the sex steroid hormone progesterone, a hormone that is critical for the establishment and maintenance of pregnancy.' Because the patient's progesterone rises right after ovulation and supports the endometrium, the source must be the newly luteinized follicular cells, not the pituitary or a degenerating remnant. (Choice A) The anterior pituitary secretes the gonadotropins LH and FSH, not progesterone — the text notes the pituitary 'responds by secreting large amounts of LH and FSH into the bloodstream.' (Choice B) During the follicular phase the dominant follicle's granulosa and theca cells primarily produce estradiol, not progesterone; 'the release of LH also stimulates the granulosa and theca cells of the follicles to produce the sex steroid hormone estradiol.' (Choice C) The corpus albicans is the nonfunctional remnant that forms when progesterone secretion ends — 'the corpus luteum will stop secreting progesterone and degrade into the corpus albicans' — so it does not sustain the endometrium. (Choice D) This correctly identifies the corpus luteum, formed by LH-driven luteinization, as the post-ovulatory source of the progesterone that maintains the endometrium. This is a Scientific Reasoning and Problem Solving question because it requires using the observed timing and effect of the progesterone rise to deduce which structure produces it and what endocrine event created that structure.$ex12$, 'medium', '3B', $cc12$Reproductive Endocrinology (BIO)$cc12$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a12A$Attributing a downstream hormone to the upstream gland that only releases tropic hormones (pituitary secretes progesterone)$a12A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a12B$Correct cell type and source organ but wrong hormone/phase (granulosa-theca make progesterone in follicular phase rather than estradiol)$a12B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a12C$Assigning a secretory role to the degenerating remnant whose formation actually marks the end of secretion (corpus albicans secretes progesterone)$a12C$ FROM q;

-- Q13 [Female Hormones: Estrogen & Progesterone | medium | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub13$Female Hormones: Estrogen & Progesterone$sub13$, $qt13$During the mid-follicular phase, several growing tertiary follicles in a person's ovary secrete increasing amounts of estradiol, and plasma estrogen climbs well above its early-cycle baseline. A physiologist samples the blood at this moment and asks what the rising estrogen will do to pituitary FSH output and to the cohort of developing follicles.$qt13$, $op13$[{"label": "A", "text": "Rising estrogen lowers FSH through negative feedback on the hypothalamus and pituitary, so most of the developing follicles undergo atresia."}, {"label": "B", "text": "Rising estrogen raises FSH through positive feedback on the hypothalamus and pituitary, so more developing follicles are recruited to grow."}, {"label": "C", "text": "Rising estrogen leaves FSH unchanged because progesterone alone feeds back on the pituitary, so the developing follicles continue growing."}, {"label": "D", "text": "Rising estrogen lowers FSH by acting directly on the ovarian follicles rather than the pituitary, so most of the developing follicles undergo atresia."}]$op13$::jsonb, 'A', $ex13$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is A because, during the mid-follicular phase, high plasma estrogen from the growing follicles drives a classic negative-feedback loop that suppresses gonadotropin output, lowering FSH and starving most follicles of the support they need to survive. The text states that "high concentrations of estrogen will stimulate the hypothalamus and pituitary to reduce the production of GnRH, LH, and FSH," and that "because the large tertiary follicles require FSH to grow and survive at this point, this decline in FSH caused by negative feedback leads most of them to die (atresia)." Only one follicle, the dominant follicle, typically survives this drop in FSH. The switch to positive feedback occurs only later, when the lone dominant follicle produces such extreme estrogen levels that normal negative feedback fails. (Choice A) is correct: estrogen's negative feedback at the hypothalamus and pituitary lowers FSH, and the FSH decline causes atresia of most follicles. (Choice B) reverses the feedback direction; the positive feedback loop "only occurs at this point in the cycle"—near ovulation with the dominant follicle—not in the mid-follicular phase. (Choice C) is a partial truth because progesterone does suppress gonadotropins, but estrogen also exerts negative feedback during the follicular phase, so FSH does fall. (Choice D) misplaces the feedback target; estrogen acts on the hypothalamus and pituitary to reduce gonadotropin output, not directly on the ovarian follicles. This is a Scientific Reasoning and Problem Solving question because it requires predicting the direction of a hormonal feedback response from a described physiological scenario and tracing that change to its downstream effect on follicle survival.$ex13$, 'medium', '3B', $cc13$Reproductive Endocrinology (BIO)$cc13$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a13B$Treats estrogen's feedback as positive (FSH rises) during the mid-follicular phase, when in fact positive feedback occurs only later with the dominant follicle's extreme estrogen output.$a13B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a13C$Correctly notes progesterone inhibits gonadotropins but wrongly denies that estrogen also exerts negative feedback in the follicular phase, concluding FSH is unchanged.$a13C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a13D$Keeps the correct direction (FSH falls, atresia) but misidentifies the feedback target as the ovarian follicles rather than the hypothalamus and pituitary.$a13D$ FROM q;

-- Q14 [Female Hormones: Estrogen & Progesterone | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub14$Female Hormones: Estrogen & Progesterone$sub14$, $qt14$A reproductive physiologist tracks a patient on day 22 of her cycle and confirms that a corpus luteum is actively secreting hormone and that no new dominant follicle is being recruited in either ovary. She wants to identify the single mechanism that best accounts for this suppression of new follicle recruitment during the luteal phase.$qt14$, $op14$[{"label": "A", "text": "Progesterone from the corpus luteum exerts positive feedback that keeps FSH and LH elevated, but the ovary has temporarily stopped responding to them."}, {"label": "B", "text": "Progesterone from the corpus luteum exerts negative feedback at the hypothalamus and pituitary, holding GnRH, FSH, and LH low until the corpus luteum degrades."}, {"label": "C", "text": "Estrogen from the corpus luteum exerts the negative feedback that suppresses gonadotropins, while progesterone acts only on the uterine lining."}, {"label": "D", "text": "Inhibin from the corpus luteum keeps FSH low while LH remains high to maintain the luteal structure and block new recruitment."}]$op14$::jsonb, 'B', $ex14$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is B because the luteinized cells of the corpus luteum produce large amounts of progesterone, and progesterone triggers negative feedback at the hypothalamus and pituitary that holds GnRH, LH, and FSH low so that no new dominant follicle is recruited. The text states the corpus luteum's cells "begin to produce large amounts of the sex steroid hormone progesterone" and that "Progesterone triggers negative feedback at the hypothalamus and pituitary, which keeps GnRH, LH, and FSH secretions low, so no new dominant follicles develop at this time" (AP 2e L56496, L56498-56499). Recruitment resumes only when the corpus luteum degrades: with "reduced progesterone secretion, FSH and LH are once again stimulated, and the follicular phase begins again" (AP 2e). The suppression is therefore caused by progesterone-driven negative feedback that lowers all three reproductive signaling hormones. (Choice A) is wrong because progesterone exerts negative feedback that lowers FSH and LH, not positive feedback that keeps them elevated; the gonadotropins are low, not high. (Choice B) is correct because it correctly attributes the suppression to progesterone's negative feedback keeping GnRH, FSH, and LH low until the corpus luteum degrades. (Choice C) is a partial truth because the corpus luteum does produce some estrogen, but the text attributes the luteal-phase feedback suppression specifically to progesterone, not estrogen. (Choice D) confuses an adjacent fact: inhibin from follicle cells does suppress FSH, but the text attributes the luteal-phase suppression of GnRH, FSH, and LH to progesterone's negative feedback, and LH is held low during this phase rather than staying high. This is a Scientific Reasoning and Problem Solving question because it requires chaining the corpus luteum's progesterone output to a negative-feedback effect on three signaling hormones and then to the downstream consequence that no new follicle is recruited until the structure degrades.$ex14$, 'hard', '3B', $cc14$Reproductive Endocrinology (BIO)$cc14$, 'biology', 2, 160
  ) RETURNING id
)
