UNION ALL SELECT id, 'B', 'process_step_confusion', $a20B$treats loss of progesterone as sufficient to trigger an LH surge and re-ovulation, skipping the high-estrogen positive-feedback switch and ignoring that the follicle is already luteinized/expelled$a20B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a20C$claims removing the progesterone source raises progesterone and thickens the endometrium, the opposite of the actual drop and breakdown$a20C$ FROM q;

-- Q21 [Pregnancy & Menopause | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub21$Pregnancy & Menopause$sub21$, $qt21$A blastocyst implants into the endometrium, and its trophoblast cells begin secreting a hormone into the maternal bloodstream. A clinician predicts that this hormone prevents the corpus luteum from degenerating so that progesterone and estrogen levels stay elevated. Which hormone is the clinician describing?$qt21$, $op21$[{"label": "A", "text": "Human chorionic gonadotropin (hCG), which directs the corpus luteum to survive and keep producing progesterone and estrogen"}, {"label": "B", "text": "Luteinizing hormone (LH), which surges to trigger ovulation of the dominant follicle"}, {"label": "C", "text": "Follicle-stimulating hormone (FSH), which stimulates a new cohort of tertiary follicles to grow"}, {"label": "D", "text": "Inhibin, which is secreted by granulosa cells to suppress pituitary FSH release"}]$op21$::jsonb, 'A', $ex21$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is A because after the blastocyst implants, the trophoblast secretes human chorionic gonadotropin (hCG), the hormone that rescues the corpus luteum from its normal degeneration. The text states that "the trophoblast secretes human chorionic gonadotropin (hCG), a hormone that directs the corpus luteum to survive, enlarge, and continue producing progesterone and estrogen to suppress menses." By keeping the corpus luteum active, hCG sustains the high progesterone and estrogen that maintain the endometrium for the developing embryo; this matches the clinician's prediction exactly. (Choice A) is correct because hCG is the trophoblast/chorion-derived hormone whose primary action is maintaining the corpus luteum and its steroid output. (Choice B) is wrong because LH surges before pregnancy to trigger ovulation of the dominant follicle, not to rescue the corpus luteum after implantation. (Choice C) is wrong because FSH stimulates the growth of a cohort of tertiary follicles early in the ovarian cycle, an action irrelevant to maintaining an existing corpus luteum. (Choice D) is wrong because inhibin from granulosa cells suppresses pituitary FSH release rather than sustaining progesterone production. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the identity and primary endocrine action of the hormone secreted by the trophoblast after implantation.$ex21$, 'easy', '3B', $cc21$Reproductive Endocrinology (BIO)$cc21$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'adjacent_fact', $a21B$Correct hormone from a different phase of the cycle (LH ovulation surge) substituted for the pregnancy-maintenance hormone$a21B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a21C$Gonadotropin with a real but unrelated action (FSH driving follicle growth) offered in place of corpus-luteum maintenance$a21C$ FROM q
