-- Q22 [Pregnancy & Menopause | medium | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub22$Pregnancy & Menopause$sub22$, $qt22$A few days after a blastocyst implants, a researcher administers a drug that selectively blocks all hCG receptor signaling in the mother. Tracking the early pregnancy over the following two weeks, which outcome is the researcher most likely to observe?$qt22$, $op22$[{"label": "A", "text": "The placenta immediately secretes its own progesterone, so progesterone stays high and the pregnancy continues unaffected"}, {"label": "B", "text": "The corpus luteum regresses and stops making progesterone, so the endometrium breaks down and the early pregnancy is lost"}, {"label": "C", "text": "The anterior pituitary releases an LH surge that re-luteinizes the follicle and rescues the corpus luteum from regression"}, {"label": "D", "text": "Estrogen from the corpus luteum rises sharply and thickens the endometrium further, stabilizing the implantation site"}]$op22$::jsonb, 'B', $ex22$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is B because hCG from the trophoblast is the signal that rescues the corpus luteum, and removing that signal lets the corpus luteum regress so progesterone falls and the endometrium is shed. After implantation the trophoblast secretes hCG, "a hormone that directs the corpus luteum to survive, enlarge, and continue producing progesterone and estrogen to suppress menses." If that signal is blocked, the situation mirrors a non-pregnant luteal phase: the corpus luteum "will stop secreting progesterone and degrade into the corpus albicans," and "without progesterone, the endometrium thins... endometrial tissue dies and blood, pieces of the endometrial tissue, and white blood cells are shed." With the endometrium shed, the implanted embryo cannot be maintained and the pregnancy fails. (Choice A) is wrong because during these early weeks "the pregnancy hormones are primarily generated by the corpus luteum," and the placenta only "gradually takes over... during weeks 12–17," so it cannot immediately compensate. (Choice B) is correct because blocking hCG removes the rescue signal, causing luteal regression, falling progesterone, endometrial breakdown, and loss of the pregnancy. (Choice C) is wrong because corpus luteum maintenance after implantation depends on hCG, not on pituitary LH, and the high progesterone of the luteal phase "triggers negative feedback at the hypothalamus and pituitary, which keeps GnRH, LH, and FSH secretions low," so no rescuing LH surge occurs. (Choice D) is wrong because the regressing corpus luteum stops producing both progesterone and estrogen, so estrogen falls rather than rising to thicken the endometrium. This is a Scientific Reasoning and Problem Solving question because it requires predicting a multi-step downstream physiological consequence of a pharmacological perturbation rather than recalling a stated fact.$ex22$, 'medium', '3B', $cc22$Reproductive Endocrinology (BIO)$cc22$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a22A$placenta-takeover-timing-confusion: true that the placenta eventually makes progesterone, but not until weeks 12–17, so it cannot compensate immediately$a22A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a22C$pituitary-LH-rescue: invokes pituitary LH to save the corpus luteum, reversing the true direction in which high luteal progesterone suppresses LH and hCG (not LH) maintains the corpus luteum$a22C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a22D$selective-estrogen-rise: assumes estrogen rises when the corpus luteum is failing, ignoring that luteal regression halts both progesterone and estrogen output$a22D$ FROM q;

-- Q23 [Pregnancy & Menopause | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub23$Pregnancy & Menopause$sub23$, $qt23$A patient is 15 weeks pregnant, and her blood work shows that hCG has fallen well below its early peak even though circulating progesterone and estrogen remain high and continue to climb. Which event BEST accounts for the sustained high levels of these two steroids despite the declining hCG and corpus luteum?$qt23$, $op23$[{"label": "A", "text": "The anterior pituitary resumes secreting high FSH and LH, which drive the ovary to produce more progesterone and estrogen"}, {"label": "B", "text": "The endometrial stratum functionalis begins secreting its own progesterone and estrogen, independent of any ovarian or placental source"}, {"label": "C", "text": "The placenta has matured enough to synthesize and secrete progesterone and estrogen itself, replacing the degenerating corpus luteum"}, {"label": "D", "text": "A second corpus luteum forms from a newly recruited follicle and sustains progesterone output through the rest of gestation"}]$op23$::jsonb, 'C', $ex23$This is a Biology question that falls under the content category 'Reproductive Endocrinology (BIO)'. The answer is C because, as the corpus luteum degenerates during weeks 12-17, the placenta matures and takes over as the endocrine organ of pregnancy, synthesizing and secreting progesterone and estrogen itself. The text states that "as the placenta develops and the corpus luteum degenerates during weeks 12-17, the placenta gradually takes over as the endocrine organ of pregnancy" and that "the placenta takes over the synthesis and secretion of progesterone throughout pregnancy as the corpus luteum degenerates" (A&P 2e, lines 58186-58207). hCG's main early job is to keep the corpus luteum alive, so once the placenta becomes the steroid source, falling hCG and a degenerating corpus luteum no longer threaten the steroid supply. OpenStax Biology 2e confirms that by the second trimester "the placenta has taken over... the production of estrogen and progesterone from the corpus luteum, which has degenerated" (Biology 2e, lines 57495-57496). (Choice A) The pituitary does not resume high FSH and LH; both estrogen and progesterone actively "suppress FSH and LH," so gonadotropins remain inhibited rather than driving new ovarian steroid output. (Choice B) The stratum functionalis is the hormone-responsive layer that "grows and thickens in response to increased levels of estrogen and progesterone," not a source that secretes those steroids itself. (Choice C) is correct because the matured placenta itself becomes the synthetic source of progesterone and estrogen, replacing the corpus luteum. (Choice D) No new corpus luteum forms, because pregnancy keeps FSH and LH suppressed so "no new dominant follicles develop," and the existing corpus luteum is degenerating rather than being supplemented. This is a Scientific Reasoning and Problem Solving question because it requires interpreting a clinical hormone profile (low hCG with high, rising steroids) and reasoning backward to the mechanism of the placental endocrine handoff that resolves the apparent contradiction.$ex23$, 'medium', '3B', $cc23$Reproductive Endocrinology (BIO)$cc23$, 'biology', 2, 105
  ) RETURNING id
)
